import {setLogger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

describe('Tool rejection logging [spec: specs/hal-engine-tool-input-validation/spec.md#4]', () => {
  it('logs the rejected nested field and type without exposing its value', async () => {
    const records: {level: string; category: string; message: string; fields?: Record<string, unknown>}[] = [];
    const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) => {
      records.push({level, category, message, fields});
    };
    setLogger({debug: record('DEBUG'), info: record('INFO'), warn: record('WARN'), error: record('ERROR')});
    try {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'weather',
          description: 'Weather at coordinates',
          inputSchema: {
            type: 'object',
            properties: {
              coordinates: {type: 'object', properties: {latitude: {type: 'number'}}},
            },
          },
        },
        async input => JSON.stringify(input)
      );
      const response = await registry.execute('weather', {
        coordinates: {latitude: 'private-person@example.com'},
      });

      expect({response, records, output: JSON.stringify({response, records})}).toEqual({
        response: {result: expect.stringMatching(/coordinates\\/latitude.*number/)},
        records: [
          {
            level: 'WARN',
            category: 'tool',
            message: 'input rejected',
            fields: {name: 'weather', result: response.result},
          },
        ],
        output: expect.not.stringContaining('private-person@example.com'),
      });
    } finally {
      setLogger();
    }
  });
});
EOF
 timeout 300 npm test -- --runTestsByPath src/orchestration/tools/registry.rejection-log.test.ts --runInBand"
